<?php
declare(strict_types=1);

function esc(mixed $value): string { return htmlspecialchars((string)$value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function jsonData(string $file): array {
    if (!is_file($file) || !is_readable($file)) return [];
    $json = file_get_contents($file);
    if ($json === false) return [];
    $data = json_decode($json, true);
    return is_array($data) ? $data : [];
}

$data = jsonData(__DIR__ . '/../data/jamoa.json');
$home = jsonData(__DIR__ . '/../data/home.json');
$brand = is_array($home['brand'] ?? null) ? $home['brand'] : [];
$name = (string)($brand['name'] ?? 'CHIMYON SCHOOL');
$team = is_array($data['team'] ?? null) ? $data['team'] : [];
$intro = (string)($data['intro'] ?? 'Chimyon School jamoasi haqida tasdiqlangan ma’lumotlar shu sahifada taqdim etiladi.');
$heroImage = (string)($data['hero_image'] ?? '');
?>
